"""Render rows of strings as a GitHub markdown table."""


def _cell(c):
    return c.strip().replace("|", "\\|")


def to_markdown(rows):
    if not rows:
        raise ValueError("no rows")
    width = len(rows[0])
    if width == 0:
        raise ValueError("header has no cells")
    for i, r in enumerate(rows[1:], start=2):
        if len(r) != width:
            raise ValueError(f"row {i} has {len(r)} cells, expected {width}")
    lines = [[_cell(c) for c in rows[0]], ["---"] * width]
    lines += [[_cell(c) for c in r] for r in rows[1:]]
    return "\n".join("| " + " | ".join(r) + " |" for r in lines)
